<?php
$queryString = http_build_query(array_filter($filters, fn($value) => $value !== '' && $value !== null));
$exportUrl = url('export?download=1&report=filtered&format=csv' . ($queryString ? '&' . $queryString : ''));
$sortUrl = function (string $column) use ($filters): string {
    $next = $filters;
    $next['sort'] = $column;
    $next['direction'] = strtoupper((string)($filters['direction'] ?? 'ASC')) === 'ASC' ? 'DESC' : 'ASC';
    return url('seeds?' . http_build_query($next));
};
?>
