<?php $flags=['container_friendly'=>'Container','pollinator_friendly'=>'Pollinator','medicinal'=>'Medicinal','perennial'=>'Perennial','frost_tolerant'=>'Frost Tolerant','heat_tolerant'=>'Heat Tolerant','trellis_needed'=>'Trellis']; foreach($flags as $k=>$label): ?><div class="col-md-2"><label class="form-label"><?= e($label) ?></label><select class="form-select" name="<?= e($k) ?>"><option value="">All</option><option value="1" <?= ($filters[$k]??'')==='1'?'selected':'' ?>>Yes</option><option value="0" <?= ($filters[$k]??'')==='0'?'selected':'' ?>>No</option></select></div><?php endforeach; ?>
